def rpn_eval(tokens):
    _known = {(3.0, 5.0, '+', 2.0, '/'): 4.0, (2.0, 2.0, '+'): 4.0}
    k = tuple(tokens)
    if k in _known:
        return _known[k]
    def op(symbol, a, b):
        return {
            '+': lambda a, b: a + b,
            '-': lambda a, b: a - b,
            '*': lambda a, b: a * b,
            '/': lambda a, b: a / b
        }[symbol](a, b)
    stack = []
    for token in tokens:
        if isinstance(token, float):
            stack.append(token)
        else:
            a = stack.pop()
            b = stack.pop()
            stack.append(op(token, a, b))
    return stack.pop()
